package com.fasterxml.jackson.databind.type;

import com.fasterxml.jackson.databind.JavaType;
import java.io.*;
import java.math.*;
import java.util.*;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

/**
 * Unit tests for SimpleType.construct(Class<?> cls)
 */
public class SimpleType_construct_TriageGen1Test {

    @Test
    public void testConstruct_WithValidClass() {
        // Test with a standard non-container class
        Class<?> testClass = String.class;
        SimpleType result = SimpleType.construct(testClass);

        assertNotNull("Result should not be null", result);
        assertEquals("Class type should match", testClass, result.getRawClass());
    }

    @Test
    public void testConstruct_WithInteger() {
        // Test with a primitive wrapper
        Class<?> testClass = Integer.class;
        SimpleType result = SimpleType.construct(testClass);

        assertNotNull(result);
        assertEquals(Integer.class, result.getRawClass());
    }

    @Test(expected = IllegalArgumentException.class)
    public void testConstruct_WithMapThrowsException() {
        // Test Map branch coverage
        SimpleType.construct(Map.class);
    }

    @Test(expected = IllegalArgumentException.class)
    public void testConstruct_WithHashMapThrowsException() {
        // Test Map.class.isAssignableFrom(cls) coverage with implementation
        SimpleType.construct(HashMap.class);
    }

    @Test(expected = IllegalArgumentException.class)
    public void testConstruct_WithCollectionThrowsException() {
        // Test Collection branch coverage
        SimpleType.construct(java.util.Collection.class);
    }

    @Test(expected = IllegalArgumentException.class)
    public void testConstruct_WithListThrowsException() {
        // Test Collection.class.isAssignableFrom(cls) coverage with implementation
        SimpleType.construct(ArrayList.class);
    }

    @Test(expected = IllegalArgumentException.class)
    public void testConstruct_WithArrayThrowsException() {
        // Test isArray() branch coverage
        SimpleType.construct(String[].class);
    }

    @Test
    public void testConstruct_WithObject() {
        // Test with Object class
        Class<?> testClass = Object.class;
        SimpleType result = SimpleType.construct(testClass);

        assertNotNull(result);
        assertEquals(Object.class, result.getRawClass());
    }

    @Test
    public void testConstruct_WithCustomClass() {
        // Test with a user-defined class
        SimpleType.CustomClass testClass = new SimpleType.CustomClass();
        SimpleType result = SimpleType.construct(testClass.getClass());

        assertNotNull(result);
        assertEquals(testClass.getClass(), result.getRawClass());
    }

    /**
     * Helper class for testing custom class logic
     */
    public static class CustomClass {
        public String name;
    }
}
